568		trunc := limit > 0 && total > limit
569		if trunc {
570			sessions = sessions[:limit]
571		}
572		nodes := make([]vizGNode, 0, len(sessions))
573		fileMap := map[string][]string{}
574		for _, se := range sessions {
575			created := ""
576			if !se.CreatedAt.IsZero() {
577				created = se.CreatedAt.UTC().Format("2006-01-02 15:04Z")
578			}
579			files := ""
580			if n := len(se.FilesTouched); n > 0 {
581				files = fmt.Sprintf("%d files", n)
582			}
583			cps := ""
584			if se.CheckpointsCount > 0 {
585				cps = fmt.Sprintf("%d checkpoints", se.CheckpointsCount)
586			}
587			name := vizJoinMeta(se.Agent, se.Model)
588			if name == "" {
589				name = "session " + vizShortID(se.SessionID)
590			}
591			text := ""
592			if se.Summary != nil {
593				text = firstNonEmpty(se.Summary.Intent, se.Summary.Outcome)
594			}
595			link := s.sessionLink(se.SessionID)
596			label := ""
597			if link != "" {
598				label = "Open in Entire"
599			}
600			nodes = append(nodes, vizGNode{ID: se.SessionID, Name: name, Kind: se.Kind, Group: "session", Color: colorSession, Text: text, Meta: vizJoinMeta(created, files, cps), Link: link, LinkLabel: label})
601			for _, fp := range se.FilesTouched {
602				if fp = strings.TrimSpace(fp); fp != "" {
603					fileMap[fp] = append(fileMap[fp], se.SessionID)
604				}
605			}
606		}
607		edges := linkBySharedKey(fileMap, "shared file", 8)
608		writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: nodes, Edges: edges, Total: total, Truncated: trunc})
609	}
