845			if d.Path != "" {
846				pathMap[d.Path] = append(pathMap[d.Path], d.ID)
847			}
848		}
849		edges := linkBySharedKey(pathMap, "same file", 8)
850		writeJSONHTTP(w, http.StatusOK, vizFeatureGraph{Nodes: nodes, Edges: edges, Total: total, Truncated: trunc})
851	}
