985	func (s *vizServer) handleNode(w http.ResponseWriter, r *http.Request) {
986		id := strings.TrimSpace(r.URL.Query().Get("id"))
987		resp := vizNodeResp{Neighbors: []vizNode{}, Relations: []vizEdge{}}
988		if id == "" {
989			writeJSONHTTP(w, http.StatusBadRequest, vizNodeResp{Warnings: []string{"missing id"}})
990			return
991		}
992		sem := s.semanticSource()
993		if sem == nil {
994			resp.Warnings = append(resp.Warnings, "no semantic graph")
995			writeJSONHTTP(w, http.StatusOK, resp)
996			return
997		}
998		node, neighbors, rels, err := s.nodeDetail(sem, id)
999		if err != nil {
1000			resp.Warnings = append(resp.Warnings, err.Error())
1001			writeJSONHTTP(w, http.StatusOK, resp)
1002			return
1003		}
1004		if node == nil {
1005			writeJSONHTTP(w, http.StatusNotFound, vizNodeResp{Neighbors: []vizNode{}, Relations: []vizEdge{}, Warnings: []string{"symbol not found: " + id}})
1006			return
1007		}
1008		resp.Symbol = nodeJSON(*node)
1009		resp.Snippet = node.Blob
1010		if l := s.sourceLink(node.FilePath, node.StartLine); l != "" {
1011			resp.Link = l
1012			resp.LinkLabel = "View source"
1013		}
1014		for i := range neighbors {
1015			resp.Neighbors = append(resp.Neighbors, nodeJSON(neighbors[i]))
1016		}
1017		for i := range rels {
1018			resp.Relations = append(resp.Relations, edgeJSON(rels[i]))
1019		}
1020		writeJSONHTTP(w, http.StatusOK, resp)
1021	}
1022	
1023	func (s *vizServer) handleSearch(w http.ResponseWriter, r *http.Request) {
1024		q := strings.TrimSpace(r.URL.Query().Get("q"))
1025		limit := 25
1026		if v := r.URL.Query().Get("limit"); v != "" {
1027			if n, err := strconv.Atoi(v); err == nil && n > 0 {
1028				limit = n
1029			}
1030		}
1031		resp := vizSearchResp{Hits: []vizHit{}}
1032		if q == "" {
1033			writeJSONHTTP(w, http.StatusOK, resp)
1034			return
1035		}
1036		// Symbol matches first so ⌘K / rail search can jump straight to a graph node.
1037		if sem := s.semanticSource(); sem != nil {
1038			if syms, _, _, err := semanticContextFacts(s.brainDir, sem, q, limit, 0); err == nil {
1039				for _, sy := range syms {
1040					resp.Hits = append(resp.Hits, vizHit{Source: "symbol", ID: sy.ID, Title: sy.Name, Text: sy.QualifiedName, Kind: sy.Kind, Path: sy.FilePath, Line: sy.StartLine})
1041				}
1042			}
1043		}
1044		// Memory hits (facts / history / docs), same code path as `entire brain search`.
1045		if u, err := retrieveUnified(s.brainDir, s.branch, q, limit, modeLexical); err == nil {
1046			for _, h := range u {
1047				resp.Hits = append(resp.Hits, vizHit{Source: h.Source, ID: h.ID, Title: h.Heading, Text: h.Text, Path: h.Path, Line: h.Line, Score: h.Score})
1048			}
1049		}
1050		writeJSONHTTP(w, http.StatusOK, resp)
1051	}
1052	
1053	// relationsForSymbols returns the relations among the given symbols, mirroring
1054	// the SQLite-vs-snapshot branch semanticContextFacts uses (semantic.go).
1055	func (s *vizServer) relationsForSymbols(sem *semanticSourceManifest, syms []semanticRecord, limit int) ([]semanticRecord, error) {
1056		if sem.StorePath != "" {
1057			storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
1058			if err != nil {
1059				return nil, err
1060			}
1061			return findSemanticRelationsForSymbolsInSQLite(storePath, syms, limit)
1062		}
1063		full, err := s.snapshotFullPath(sem)
1064		if err != nil {
1065			return nil, err
1066		}
1067		return findSemanticRelationsForSymbols(full, syms, limit)
1068	}
1069	
1070	// nodeDetail resolves one symbol by exact id plus its relations and neighbors,
1071	// mirroring semanticContextFacts but seeded by id rather than a search query.
1072	func (s *vizServer) nodeDetail(sem *semanticSourceManifest, id string) (*semanticRecord, []semanticRecord, []semanticRecord, error) {
1073		const limit = 80
1074		if sem.StorePath != "" {
1075			storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
1076			if err != nil {
1077				return nil, nil, nil, err
1078			}
1079			byID, err := loadSemanticSymbolsByIDsSQLite(storePath, []string{id})
1080			if err != nil {
1081				return nil, nil, nil, err
1082			}
1083			node, ok := byID[id]
1084			if !ok {
1085				return nil, nil, nil, nil
1086			}
1087			rels, err := findSemanticRelationsForSymbolsInSQLite(storePath, []semanticRecord{node}, limit*4)
1088			if err != nil {
1089				return nil, nil, nil, err
1090			}
1091			neighbors, err := s.resolveNeighbors(node, rels, func(ids []string) (map[string]semanticRecord, error) {
1092				return loadSemanticSymbolsByIDsSQLite(storePath, ids)
1093			}, limit)
1094			if err != nil {
1095				return nil, nil, nil, err
1096			}
1097			return &node, neighbors, rels, nil
1098		}
1099		full, err := s.snapshotFullPath(sem)
1100		if err != nil {
1101			return nil, nil, nil, err
1102		}
1103		byID, err := loadSemanticSymbolsByIDsSnapshot(full, []string{id})
1104		if err != nil {
1105			return nil, nil, nil, err
1106		}
1107		node, ok := byID[id]
1108		if !ok {
1109			return nil, nil, nil, nil
1110		}
1111		rels, err := findSemanticRelationsForSymbols(full, []semanticRecord{node}, limit*4)
1112		if err != nil {
1113			return nil, nil, nil, err
1114		}
1115		neighbors, err := s.resolveNeighbors(node, rels, func(ids []string) (map[string]semanticRecord, error) {
1116			return loadSemanticSymbolsByIDsSnapshot(full, ids)
1117		}, limit)
1118		if err != nil {
1119			return nil, nil, nil, err
1120		}
1121		return &node, neighbors, rels, nil
1122	}
1123	
1124	func (s *vizServer) resolveNeighbors(node semanticRecord, rels []semanticRecord, load func([]string) (map[string]semanticRecord, error), limit int) ([]semanticRecord, error) {
1125		ids := neighborCandidateIDs([]semanticRecord{node}, rels)
1126		if len(ids) == 0 {
1127			return nil, nil
1128		}
1129		byID, err := load(ids)
1130		if err != nil {
1131			return nil, err
1132		}
1133		return resolveContextNeighbors([]semanticRecord{node}, rels, byID, limit), nil
1134	}
1135	
1136	func (s *vizServer) snapshotFullPath(sem *semanticSourceManifest) (string, error) {
1137		snap, err := validateSemanticSnapshotPath(sem.SnapshotPath)
1138		if err != nil {
1139			return "", err
1140		}
1141		if err := rejectSymlinkPathComponents(s.brainDir, snap); err != nil {
1142			return "", err
1143		}
1144		return filepath.Join(s.brainDir, snap), nil
1145	}
