1147	func writeJSONHTTP(w http.ResponseWriter, code int, v any) {
1148		w.Header().Set("Content-Type", "application/json; charset=utf-8")
1149		w.WriteHeader(code)
1150		_ = json.NewEncoder(w).Encode(v)
1151	}
1152	
1153	// openBrowser best-effort opens url in the default browser. Failure never fails
1154	// the command — the URL is already printed for manual navigation.
1155	func openBrowser(url string) {
1156		var c *exec.Cmd
1157		switch runtime.GOOS {
1158		case "darwin":
1159			c = exec.Command("open", url)
1160		case "windows":
1161			c = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
1162		default:
1163			c = exec.Command("xdg-open", url)
1164		}
1165		_ = c.Start()
1166	}
