211	  try {
212	    const base = key === 'sem' ? '/api/graph' : '/api/' + key;
213	    const g = await api(base + (currentLimit ? '?limit=' + currentLimit : ''));
214	    if (currentFeature !== key) return;
215	    $('loading').classList.add('hidden');
216	    const nodes = g.nodes || [];
217	    gData = { byId: Object.fromEntries(nodes.map((n) => [n.id, n])), edges: g.edges || [] };
218	    const total = g.total || nodes.length;
219	    if (!nodes.length) {
220	      $('empty').classList.remove('hidden');
221	      $('empty-title').textContent = 'Nothing here yet';
222	      $('empty-body').textContent = (g.warnings && g.warnings[0]) || `No ${f.label.toLowerCase()} yet.`;
223	      setupSlider(nodes.length, total);
224	      return;
225	    }
226	    graph.setData(nodes, g.edges || []);
227	    const shown = nodes.length;
228	    $('crumb-count').textContent = total > shown ? `${nf(shown)} of ${nf(total)}` : nf(total);
229	    setupSlider(shown, total);
230	    if (fit) [280, 900, 1800].forEach((t) => setTimeout(() => { if (graph && currentFeature === key) graph.zoomToFit(false); }, t));
231	    if (focusId) setTimeout(() => { if (currentFeature === key) openGraphNode(graph.getNode(focusId) || { id: focusId }); }, 650);
232	  } catch (e) {
233	    $('loading').classList.add('hidden'); $('empty').classList.remove('hidden');
234	    $('empty-title').textContent = 'Could not load'; $('empty-body').textContent = String(e.message || e);
235	  }
236	}
237	
238	// Configure the node-count slider for the current feature: range 50..min(total,cap).
239	function setupSlider(shown, total) {
240	  const ctl = $('node-ctl'), sl = $('node-slider');
241	  const max = Math.min(total, NODE_SLIDER_MAX);
242	  if (total <= 60 || max <= 50) { ctl.classList.add('hidden'); return; }
243	  sl.min = 50; sl.max = max; sl.step = max > 1000 ? 50 : 10;
244	  sl.value = String(currentLimit || Math.min(shown, max));
245	  $('node-slider-val').textContent = total > shown ? `${nf(shown)} / ${nf(total)}` : nf(shown);
246	  ctl.classList.remove('hidden');
247	}
248	const onSliderChange = debounce((v) => { currentLimit = v; loadFeatureGraph(currentFeature, null, true); }, 260);
249	$('node-slider').addEventListener('input', (e) => {
250	  const v = parseInt(e.target.value, 10) || 50;
251	  $('node-slider-val').textContent = nf(v);
252	  onSliderChange(v);
253	});
254	
255	function openGraphNode(n) {
256	  if (!n) return;
257	  if (currentFeature === 'sem' || currentFeature === 'replay') { openNode(n.id); return; }
258	  openFeatureNode(n.id);
259	}
260	
261	// ---------- tooltip ----------
262	const tip = $('tooltip');
263	let lastTipId = null;
264	function showTooltip(n, clientX, clientY) {
265	  if (!n) { tip.classList.remove('show'); lastTipId = null; return; }
266	  if (n.id !== lastTipId) { lastTipId = n.id; sfx('hover'); }
267	  const sub = n.file ? `<br><span class="k">${esc(n.file)}${n.line ? ':' + n.line : ''}</span>` : (n.meta ? `<br><span class="k">${esc(n.meta)}</span>` : '');
268	  tip.innerHTML = `<span style="color:${nodeColor(n)}">${esc(n.name || n.id)}</span> <span class="k">${esc(n.group || n.kind || '')}</span>${sub}`;
269	  tip.style.left = clientX + 'px'; tip.style.top = clientY + 'px'; tip.classList.add('show');
270	}
271	
272	// ---------- inspector ----------
273	function linkButton(o) {
274	  if (!o || !o.link) return '';
275	  return `<a class="insp-link" href="${esc(o.link)}" target="_blank" rel="noopener noreferrer">${esc(o.link_label || o.linkLabel || 'Open in Entire')} &#8599;</a>`;
276	}
277	function paintHead(n) {
278	  const col = n.color || colorForKind(n.kind), kind = $('insp-kind');
279	  kind.querySelector('.dot').style.background = col;
280	  kind.querySelector('span:last-child').textContent = n.group || n.kind || 'item';
281	  $('insp-name').textContent = n.name || n.id;
282	  $('insp-qual').textContent = n.meta || (n.qualified_name && n.qualified_name !== n.name ? n.qualified_name : '') || '';
283	  $('insp-file').textContent = n.file ? n.file + (n.line ? ':' + n.line : '') : '';
284	}
285	
286	// Semantic symbol: rich detail via /api/node (signature, snippet, neighbors, link).
287	async function openNode(id) {
288	  sfx('open');
289	  currentSel = id; ensureGraph(); graph.focus(id); app.classList.add('inspector-open');
290	  paintHead(graph.getNode(id) || { id });
291	  $('insp-body').innerHTML = '<div class="empty-note">Loading…</div>';
292	  try {
293	    const d = await api('/api/node?id=' + encodeURIComponent(id));
294	    if (currentSel !== id) return;
295	    paintHead(d.symbol || { id });
296	    let html = '';
297	    if (d.link) html += linkButton({ link: d.link, link_label: d.link_label });
298	    if (d.symbol && d.symbol.signature) html += `<div class="insp-sig">${esc(d.symbol.signature)}</div>`;
299	    if (d.snippet && d.snippet.trim() && d.snippet.trim() !== ((d.symbol && d.symbol.signature) || '').trim()) html += `<div class="insp-h">Source</div><div class="insp-sig">${esc(d.snippet.slice(0, 1400))}</div>`;
300	    const nb = d.neighbors || [];
301	    html += `<div class="insp-h">Neighbors · ${nb.length}</div>`;
302	    if (!nb.length) html += `<div class="empty-note">No linked symbols.</div>`;
303	    else {
304	      const relOf = (nid) => { for (const r of d.relations || []) { if (r.from === (d.symbol || {}).id && r.to === nid) return '→ ' + r.type; if (r.to === (d.symbol || {}).id && r.from === nid) return '← ' + r.type; } return ''; };
305	      html += nb.map((x) => `<div class="neighbor" data-id="${esc(x.id)}"><span class="dot" style="background:${nodeColor(x)}"></span><span class="n" title="${esc(x.qualified_name || x.name)}">${esc(x.name || x.id)}</span><span class="rel">${esc(relOf(x.id))}</span></div>`).join('');
306	    }
307	    const body = $('insp-body'); body.innerHTML = html;
308	    body.querySelectorAll('.neighbor').forEach((el) => el.addEventListener('click', () => openNode(el.dataset.id)));
309	  } catch (e) { $('insp-body').innerHTML = `<div class="empty-note">Could not load: ${esc(String(e.message || e))}</div>`; }
310	}
311	
312	// Feature node (fact/session/history/doc): detail comes from the loaded graph data.
313	function openFeatureNode(id) {
314	  const n = gData.byId[id];
315	  if (!n) return;
316	  sfx('open');
317	  currentSel = id; graph.focus(id); app.classList.add('inspector-open');
318	  paintHead(n);
319	  const nb = [];
320	  for (const e of gData.edges) {
321	    if (e.from === id && gData.byId[e.to]) nb.push({ node: gData.byId[e.to], rel: e.type, dir: '→' });
322	    else if (e.to === id && gData.byId[e.from]) nb.push({ node: gData.byId[e.from], rel: e.type, dir: '←' });
323	  }
324	  let html = '';
325	  html += linkButton(n);
326	  if (currentFeature === 'sessions') html += `<button class="insp-replay" data-replay="${esc(id)}">&#9654;&#65038; Replay on graph</button>`;
327	  if (n.text) html += `<div class="insp-sig">${esc(n.text)}</div>`;
328	  html += `<div class="insp-h">Connected · ${nb.length}</div>`;
329	  if (!nb.length) html += `<div class="empty-note">No links.</div>`;
330	  else html += nb.slice(0, 80).map((x) => `<div class="neighbor" data-id="${esc(x.node.id)}"><span class="dot" style="background:${nodeColor(x.node)}"></span><span class="n" title="${esc(x.node.text || x.node.name)}">${esc(x.node.name || x.node.id)}</span><span class="rel">${esc((x.dir || '') + ' ' + (x.rel || ''))}</span></div>`).join('');
331	  const body = $('insp-body'); body.innerHTML = html;
332	  body.querySelectorAll('.insp-replay').forEach((el) => el.addEventListener('click', () => startReplay(el.dataset.replay)));
333	  body.querySelectorAll('.neighbor').forEach((el) => el.addEventListener('click', () => openFeatureNode(el.dataset.id)));
334	}
335	
336	async function expandNode(n) { try { const d = await api('/api/node?id=' + encodeURIComponent(n.id)); if (graph.mergeData(d.neighbors || [], d.relations || []) > 0) graph.reheat(0.6); } catch (e) { /* best-effort */ } }
337	function closeInspector() { app.classList.remove('inspector-open'); currentSel = null; graph && graph.clearFocus(); }
338	$('insp-close').addEventListener('click', closeInspector);
339	$('insp-focus').addEventListener('click', () => currentSel && graph.focus(currentSel));
340	$('insp-expand').addEventListener('click', () => { if (currentFeature === 'sem' && currentSel) { const n = graph.getNode(currentSel); if (n) expandNode(n); } });
341	$('fit').addEventListener('click', () => graph && graph.zoomToFit());
342	
343	// ---------- session replay ----------
344	// Fetch a session's touched-file symbols as a focused subgraph, then walk the
345	// files one step at a time — lighting up each file's symbols with a growing trail.
346	let replay = null;
347	const RP_PLAY = '▶', RP_PAUSE = '⏸';
348	
349	function stopReplay() {
350	  if (replay) { clearInterval(replay.timer); replay = null; }
351	  graph && graph.clearReplay();
352	  $('replaybar').classList.add('hidden');
353	}
354	
355	async function startReplay(sessionId) {
356	  ensureGraph();
357	  stopReplay();
358	  setView('graph');
359	  currentFeature = 'replay';
360	  $('legend').classList.add('hidden');
361	  $('node-ctl').classList.add('hidden');
362	  $('insp-expand').style.display = 'none';
363	  $('crumb-title').textContent = 'Replay';
364	  $('crumb-count').textContent = '';
365	  closeInspector();
366	  $('loading').classList.remove('hidden'); $('empty').classList.add('hidden');
367	  sfx('open');
368	  try {
369	    const d = await api('/api/session/replay?id=' + encodeURIComponent(sessionId));
370	    if (currentFeature !== 'replay') return;
371	    $('loading').classList.add('hidden');
372	    const nodes = d.nodes || [];
373	    gData = { byId: Object.fromEntries(nodes.map((n) => [n.id, n])), edges: d.edges || [] };
374	    if (!nodes.length) {
375	      $('empty').classList.remove('hidden');
376	      $('empty-title').textContent = 'Nothing to replay';
377	      $('empty-body').textContent = (d.warnings && d.warnings[0]) || 'This session touched no indexed symbols.';
378	      return;
379	    }
380	    graph.setData(nodes, d.edges || []); // autoFit frames the whole subgraph as it settles
381	    replay = { steps: d.steps || [], idx: -1, playing: false, timer: null, name: (d.session && d.session.name) || 'session' };
382	    $('rp-title').textContent = replay.name;
383	    const scrub = $('rp-scrub'); scrub.min = 0; scrub.max = Math.max(0, replay.steps.length - 1); scrub.value = 0;
384	    $('replaybar').classList.remove('hidden');
385	    // Let it settle + frame the whole graph first, then start stepping through it
386	    // in place (no per-step camera jumps — that was the disorienting part).
387	    setTimeout(() => { if (currentFeature === 'replay' && replay) { graph.zoomToFit(false); replaySeek(0); replayPlay(); } }, 1100);
388	  } catch (e) {
389	    $('loading').classList.add('hidden'); $('empty').classList.remove('hidden');
390	    $('empty-title').textContent = 'Could not load replay'; $('empty-body').textContent = String(e.message || e);
391	  }
392	}
393	
394	function replayApply() {
395	  if (!replay) return;
396	  const step = replay.steps[replay.idx];
397	  const active = (step && step.ids) || [];
398	  const visited = new Set();
399	  for (let i = 0; i <= replay.idx; i++) (replay.steps[i].ids || []).forEach((id) => visited.add(id));
400	  graph.setReplay(active, visited);
401	  $('rp-step').textContent = `${replay.idx + 1} / ${replay.steps.length}`;
402	  $('rp-file').textContent = step ? `${step.file}  ·  ${step.ids.length ? step.ids.length + ' symbols' : 'no symbols'}` : '';
403	  $('rp-scrub').value = String(replay.idx);
404	  sfx('step');
405	}
406	function replaySeek(i) { if (!replay) return; replay.idx = Math.max(0, Math.min(i, replay.steps.length - 1)); replayApply(); }
407	function replayPlay() {
408	  if (!replay) return;
409	  replay.playing = true; $('rp-play').textContent = RP_PAUSE;
410	  clearInterval(replay.timer);
411	  replay.timer = setInterval(() => {
412	    if (!replay || replay.idx >= replay.steps.length - 1) { replayPause(); return; }
413	    replaySeek(replay.idx + 1);
414	  }, 1700);
415	}
416	function replayPause() { if (!replay) return; replay.playing = false; clearInterval(replay.timer); replay.timer = null; $('rp-play').textContent = RP_PLAY; }
417	function replayToggle() {
418	  if (!replay) return;
419	  if (replay.playing) { replayPause(); return; }
420	  if (replay.idx >= replay.steps.length - 1) replaySeek(0);
421	  replayPlay();
422	}
423	$('rp-play').addEventListener('click', replayToggle);
424	$('rp-prev').addEventListener('click', () => { replayPause(); replaySeek((replay ? replay.idx : 0) - 1); });
425	$('rp-next').addEventListener('click', () => { replayPause(); replaySeek((replay ? replay.idx : 0) + 1); });
426	$('rp-scrub').addEventListener('input', (e) => { replayPause(); replaySeek(parseInt(e.target.value, 10) || 0); });
427	$('rp-close').addEventListener('click', () => { stopReplay(); openFeature('sessions'); });
428	
429	// ---------- search (global) ----------
430	const results = $('results');
431	function clearSearch() { $('search').value = ''; results.innerHTML = ''; $('results-label').hidden = true; }
432	function hitColor(h) { if (h.source === 'symbol') return colorForKind(h.kind); const k = SOURCE_TO_FEATURE[h.source]; return (featureByKey[k] && featureByKey[k].hex) || 'var(--text-disabled)'; }
433	let searchSeq = 0;
434	const runSearch = debounce(async (q) => {
435	  const seq = ++searchSeq; // bump first so clearing also invalidates an in-flight fetch
436	  if (!q.trim()) { results.innerHTML = ''; $('results-label').hidden = true; return; }
437	  $('results-label').hidden = false;
438	  try { const r = await api('/api/search?q=' + encodeURIComponent(q)); if (seq !== searchSeq) return; renderResults(r.hits || []); $('results-label').textContent = `${(r.hits || []).length} results`; }
439	  catch (e) { if (seq === searchSeq) results.innerHTML = `<div class="empty-note" style="padding:8px 16px">search failed</div>`; }
440	}, 160);
441	$('search').addEventListener('input', (e) => runSearch(e.target.value));
442	
443	function renderResults(hits) {
444	  if (!hits.length) { results.innerHTML = `<div class="empty-note" style="padding:8px 16px">No matches</div>`; return; }
445	  results.innerHTML = hits.map((h, i) => `<button class="result" data-i="${i}"><span class="dot" style="background:${hitColor(h)}"></span><span class="name" title="${esc(h.text || h.title)}">${esc(h.title || h.text || h.id)}</span><span class="meta">${esc(h.source)}</span></button>`).join('');
446	  results.querySelectorAll('.result').forEach((el) => el.addEventListener('click', () => selectHit(hits[+el.dataset.i])));
447	}
448	function selectHit(h) {
449	  const key = SOURCE_TO_FEATURE[h.source] || 'sem';
450	  openFeature(key, h.id);
451	}
452	
453	// ---------- command palette ----------
454	const pal = $('palette'), palInput = $('palette-input'), palList = $('palette-list');
455	let palHits = [], palActive = 0;
456	function openPalette() { pal.classList.remove('hidden'); palInput.value = ''; palList.innerHTML = ''; palHits = []; palActive = 0; palInput.focus(); }
457	function closePalette() { pal.classList.add('hidden'); }
458	let palSeq = 0;
459	const runPalette = debounce(async (q) => {
460	  const seq = ++palSeq; // bump first so clearing also invalidates an in-flight fetch
461	  if (!q.trim()) { palList.innerHTML = ''; palHits = []; return; }
462	  try { const r = await api('/api/search?q=' + encodeURIComponent(q)); if (seq !== palSeq) return; palHits = r.hits || []; palActive = 0; renderPalette(); }
463	  catch (e) { if (seq === palSeq) palList.innerHTML = `<div class="item"><span class="name">search failed</span></div>`; }
464	}, 140);
465	function renderPalette() {
466	  palList.innerHTML = palHits.map((h, i) => `<div class="item ${i === palActive ? 'active' : ''}" data-i="${i}"><span class="dot" style="background:${hitColor(h)}"></span><span class="name">${esc(h.title || h.text || h.id)}</span><span class="src">${esc(h.source)}</span></div>`).join('');
467	  palList.querySelectorAll('.item').forEach((el) => el.addEventListener('click', () => { closePalette(); selectHit(palHits[+el.dataset.i]); }));
468	  const active = palList.querySelector('.item.active'); active && active.scrollIntoView({ block: 'nearest' });
469	}
470	palInput.addEventListener('input', (e) => runPalette(e.target.value));
471	palInput.addEventListener('keydown', (e) => {
472	  if (e.key === 'ArrowDown') { e.preventDefault(); palActive = Math.min(palActive + 1, palHits.length - 1); renderPalette(); }
473	  else if (e.key === 'ArrowUp') { e.preventDefault(); palActive = Math.max(palActive - 1, 0); renderPalette(); }
474	  else if (e.key === 'Enter') { e.preventDefault(); if (palHits[palActive]) { closePalette(); selectHit(palHits[palActive]); } }
475	});
476	pal.addEventListener('click', (e) => { if (e.target === pal) closePalette(); });
477	
478	// ---------- global keys ----------
479	window.addEventListener('keydown', (e) => {
480	  const typing = /^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName);
481	  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); pal.classList.contains('hidden') ? openPalette() : closePalette(); return; }
482	  if (e.key === 'Escape') { if (!pal.classList.contains('hidden')) return closePalette(); if (app.classList.contains('inspector-open')) return closeInspector(); if (view !== 'hub') return showHub(); }
483	  if (typing) return;
484	  if (e.key === '/') { e.preventDefault(); $('search').focus(); }
485	  else if (e.key === '0' && view === 'graph') { e.preventDefault(); graph && graph.zoomToFit(); }
486	});
487	
488	// ---------- boot (runs last, after all consts + listeners are initialized) ----------
489	(function boot() {
490	  // Paint the hub shell immediately so the page is never blank — the summary
491	  // fetch can take a few seconds on large brains. Counts + repo/branch fill in
492	  // when it resolves.
493	  renderHub({});
494	  showHub();
495	  api('/api/summary')
496	    .then((summary) => { renderSummary(summary); renderHub(summary.counts || {}); })
497	    .catch(() => { /* keep the countless hub */ });
498	})();
