141			t.Fatalf("create: %v", err)
142		}
143		// rowid 1: sym-1 -> sym-2 ; rowid 2: sym-3 -> sym-1 (both incident to the set)
144		if _, err := db.Exec(`INSERT INTO relations (from_id,to_id,type,confidence,reason) VALUES ('sym-1','sym-2','CALLS',1,''),('sym-3','sym-1','IMPORTS',1,'')`); err != nil {
